contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 firstMinSum, uint256 secondMinSum) public {
        c.SetMinSum(firstMinSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint256 minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool sumReverted;
        c.SetMinSum(secondMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            sumReverted = true;
        } else {
            sumReverted = false;
        }

        assert(sumReverted && c.MinSum() == minBefore);
    }
}

