pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 firstMinSum, uint256 secondMinSum) internal {
        try c.SetMinSum(firstMinSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool sumReverted;
        try c.SetMinSum(secondMinSum) {
            sumReverted = false;
        } catch {
            sumReverted = true;
        }
        assertTrue(sumReverted && c.MinSum() == minBefore);
    }

    function testFuzz_run(uint256 firstMinSum, uint256 secondMinSum) public {
        _run(firstMinSum, secondMinSum);
    }

    receive() external payable {}
}
